function timeRequiredToBuy(tickets: number[], k: number): number {
    let ans = 0;
    const n = tickets.length;
    for (let i = 0; i < n; ++i) {
        ans += Math.min(tickets[i], i <= k ? tickets[k] : tickets[k] - 1);
    }
    return ans;
}

class Solution {
public:
    int timeRequiredToBuy(vector<int>& tickets, int k) {
        int n=tickets.size();
        int ans=0;

        while(tickets[k]>0){
            for(int i=0; i<n; i++){
                if(tickets[i]>0){
                    tickets[i]-=1;
                    ans++;
                }
                if(tickets[k]==0)
                    return ans;
            }
        }

        return ans;
    }
};
